user_message:
Compare the typed predicate candidates against the existing registry.
Candidate predicates:
[
  {
    "name": "IDENTIFIES_MISSING_SOFTWARE_DEPENDENCY",
    "definition": "The reasoning concludes from an environment probe that software required to perform the task is absent and must be installed before the intended service configuration can proceed.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text diagnosing the environment and naming the missing capability."
      },
      {
        "name": "observation",
        "type": "observation",
        "description": "The probe result showing which required tools or services are absent."
      }
    ],
    "assertion_conditions": [
      "The observation reports that one or more task-required tools or services are unavailable.",
      "The reasoning explicitly identifies that absence as a prerequisite gap and indicates that the missing software must be supplied."
    ],
    "exclusion_conditions": [
      "The observation only enumerates installed software without demonstrating a missing requirement.",
      "The reasoning restates the task without connecting it to an observed absence."
    ]
  },
  {
    "name": "ADAPTS_TO_ABSENT_SERVICE_MANAGER",
    "definition": "The reasoning recognizes from a process or runtime observation that no service manager or init system is available and therefore selects direct daemon startup or another non-init persistence strategy.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text inferring the absence of an init system and adapting the startup strategy."
      },
      {
        "name": "observation",
        "type": "observation",
        "description": "The process or runtime listing showing that PID 1 or the environment lacks a service manager."
      }
    ],
    "assertion_conditions": [
      "The observation shows that the container or host is not running a conventional init or service manager.",
      "The reasoning explicitly infers that services cannot be managed through that absent mechanism and selects manual or direct daemon startup."
    ],
    "exclusion_conditions": [
      "The observation does not expose process or runtime state relevant to service management.",
      "The reasoning merely plans to start services without noting any absent service manager."
    ]
  },
  {
    "name": "INSTALLS_REQUIRED_DEPENDENCIES",
    "definition": "The action installs software packages that the reasoning has identified as required missing dependencies for the task.",
    "parameters": [
      {
        "name": "action",
        "type": "action",
        "description": "The package installation invocation."
      },
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The reasoning naming the packages or capabilities that must be installed."
      }
    ],
    "assertion_conditions": [
      "The reasoning identifies specific missing tools, services, or packages as prerequisites.",
      "The action invokes a package manager to install those identified dependencies."
    ],
    "exclusion_conditions": [
      "The action only refreshes package indexes without installing required dependencies.",
      "The action installs packages unrelated to the dependencies identified in the reasoning."
    ]
  },
  {
    "name": "PREPARES_ACCOUNT_FOR_KEY_AUTHENTICATION",
    "definition": "The action creates or adjusts a service account so that it can be used for remote key-based access and own service data without requiring password login.",
    "parameters": [
      {
        "name": "action",
        "type": "action",
        "description": "The account-creation and authentication-state adjustment command or script."
      }
    ],
    "assertion_conditions": [
      "The action creates a user with a usable login shell and home directory.",
      "The action sets the account password field to a non-locking marker rather than leaving the account locked.",
      "The action creates a user-owned .ssh directory with restrictive permissions and an authorized_keys file suitable for later key insertion."
    ],
    "exclusion_conditions": [
      "The action merely creates an account but leaves its authentication state locked or otherwise unusable for key login.",
      "The action adjusts unrelated account attributes without preparing remote key-based access."
    ]
  },
  {
    "name": "INITIALIZES_BARE_REPOSITORY",
    "definition": "The action initializes a bare repository configured to accept remote pushes on a designated default branch and owned by the service account.",
    "parameters": [
      {
        "name": "action",
        "type": "action",
        "description": "The repository initialization and ownership command."
      }
    ],
    "assertion_conditions": [
      "The action creates a bare repository at the intended service path.",
      "The action sets HEAD or an equivalent symbolic reference to the designated default branch.",
      "The action assigns repository ownership to the service account or otherwise enables that account to receive pushes."
    ],
    "exclusion_conditions": [
      "The action initializes a non-bare working repository instead of a push target.",
      "The repository is left without the intended default branch or without ownership suitable for the service account."
    ]
  },
  {
    "name": "CONFIGURES_PUSH_TRIGGERED_DEPLOYMENT",
    "definition": "The action installs a repository hook that, when a branch is pushed, checks out the pushed content into the directory served by the web server.",
    "parameters": [
      {
        "name": "action",
        "type": "action",
        "description": "The hook-writing or hook-installation action."
      }
    ],
    "assertion_conditions": [
      "The action writes an executable repository hook in the repository's hook directory.",
      "The hook logic reads pushed references and performs a work-tree checkout or equivalent deployment into the served document root.",
      "The hook handles branch references and excludes non-branch or deletion events."
    ],
    "exclusion_conditions": [
      "The hook only logs, notifies, or performs an action unrelated to deploying pushed content.",
      "Deployment into the served directory is not part of the hook behavior."
    ]
  },
  {
    "name": "CONFIGURES_SERVICE_ENDPOINT",
    "definition": "The action writes or replaces the active configuration of a network service so that the service listens on the required port and serves the intended document root.",
    "parameters": [
      {
        "name": "action",
        "type": "action",
        "description": "The configuration-writing action that defines the service endpoint."
      }
    ],
    "assertion_conditions": [
      "The action writes configuration specifying the task-required listen port.",
      "The action specifies the document root from which the service should serve content.",
      "The configuration is written to an active configuration path or to a path that is enabled by the service."
    ],
    "exclusion_conditions": [
      "The action edits an inactive sample configuration that is not enabled.",
      "The action changes unrelated directives without defining the required port and document root."
    ]
  },
  {
    "name": "PREPARES_DEPLOYMENT_DIRECTORY",
    "definition": "The action creates or adjusts ownership and permissions of the directory served by the web server so that the deployment account can write content and the server process can read it.",
    "parameters": [
      {
        "name": "action",
        "type": "action",
        "description": "The directory preparation command."
      }
    ],
    "assertion_conditions": [
      "The action creates the served directory or confirms its existence.",
      "The action assigns ownership or permissions so that the deployment account can write to the directory.",
      "The resulting permissions still allow the web server process to read the deployed content."
    ],
    "exclusion_conditions": [
      "The action only reads or lists the directory without preparing it for deployment.",
      "The action changes ownership or permissions in a way that prevents the web server from reading deployed files."
    ]
  },
  {
    "name": "VALIDATES_AND_ENABLES_SERVICE_CONFIGURATION",
    "definition": "The action verifies that the intended service configuration is active and syntactically valid, and conditions service startup on that verification succeeding.",
    "parameters": [
      {
        "name": "action",
        "type": "action",
        "description": "The validation and activation command sequence."
      }
    ],
    "assertion_conditions": [
      "The action inspects whether the intended configuration is enabled or linked into the active configuration set.",
      "The action runs a configuration syntax or consistency check for the service.",
      "Startup of the service is chained to success of the validation step."
    ],
    "exclusion_conditions": [
      "The service is started without any configuration validation.",
      "A validation command is run but its failure does not prevent startup."
    ]
  },
  {
    "name": "STARTS_SERVICE_DAEMONS_DIRECTLY",
    "definition": "The action launches required long-running service daemons directly rather than through an init or service manager, including preparing any runtime directories or host keys needed for those daemons to start.",
    "parameters": [
      {
        "name": "action",
        "type": "action",
        "description": "The daemon-launching command or script."
      }
    ],
    "assertion_conditions": [
      "The action invokes daemon binaries or service-start commands to launch the required network services.",
      "The action prepares necessary runtime directories, host keys, or equivalent startup prerequisites.",
      "The launched processes are intended to remain running independently of the invoking shell."
    ],
    "exclusion_conditions": [
      "The action only installs packages without launching the services.",
      "The action relies on a service manager or init system that is absent from the environment.",
      "The action starts only a transient foreground process rather than the required long-running daemon."
    ]
  },
  {
    "name": "ESTABLISHES_LOCAL_HOSTNAME_RESOLUTION",
    "definition": "The action adds a local name-resolution mapping so that the service hostname used in client commands resolves to the local or container address.",
    "parameters": [
      {
        "name": "action",
        "type": "action",
        "description": "The hostname or resolver configuration action."
      }
    ],
    "assertion_conditions": [
      "The action adds or modifies a local hosts-file or equivalent resolver entry.",
      "The entry maps the task's service hostname to a local or container-reachable address."
    ],
    "exclusion_conditions": [
      "The action changes the machine's own hostname rather than adding a service-name mapping.",
      "The action only relies on an external DNS service without adding the local mapping."
    ]
  },
  {
    "name": "REPORTS_EXPECTED_DAEMONS_RUNNING",
    "definition": "The observation contains process or listener evidence showing that the expected service daemons are running and active.",
    "parameters": [
      {
        "name": "observation",
        "type": "observation",
        "description": "The process or listener listing returned by the environment."
      }
    ],
    "assertion_conditions": [
      "The observation enumerates running processes corresponding to the expected service daemons.",
      "The evidence includes active daemon processes, worker processes, or listeners rather than only installation artifacts."
    ],
    "exclusion_conditions": [
      "The observation contains only installation logs or package-management output.",
      "The expected daemon processes are absent from the listing."
    ]
  },
  {
    "name": "GUIDES_CONFIGURATION_CHANGE",
    "definition": "The observation exposes the current configuration's relevant values or activation structure, and a subsequent action modifies that same configuration to the required values.",
    "parameters": [
      {
        "name": "observation",
        "type": "observation",
        "description": "The observation revealing existing configuration values or activation structure."
      },
      {
        "name": "action",
        "type": "action",
        "description": "The later action that changes that configuration."
      }
    ],
    "assertion_conditions": [
      "The observation shows current configuration details such as a listen directive, document root, or active-configuration link.",
      "A subsequent action writes or replaces that same configuration, changing the identified values to the task-required values."
    ],
    "exclusion_conditions": [
      "The observation supplies an operational data payload rather than configuration structure or values.",
      "The subsequent action modifies an unrelated configuration without using the observed values or structure."
    ]
  }
]

Existing registry:
[
  {
    "name": "IS_PLAN",
    "definition": "The reasoning explicitly expresses an intended future action or sequence of actions that the agent intends to carry out next.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text expressing the intended future action or sequence of actions."
      }
    ],
    "assertion_conditions": [
      "The reasoning identifies at least one action to be performed later, such as inspecting a file, writing content, compiling, or verifying output.",
      "The intended action is stated prospectively rather than reported as already done."
    ],
    "exclusion_conditions": [
      "The reasoning only reports or summarizes actions already completed.",
      "The reasoning only restates file content or tool output without expressing an intended next action."
    ]
  },
  {
    "name": "DIAGNOSES_OBSERVED_FAILURE",
    "definition": "The reasoning explains the cause of a failure reported by an observation and derives a corrective approach from that explanation.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text explaining why the observed failure occurred and what should change."
      },
      {
        "name": "failure",
        "type": "observation",
        "description": "The observation reporting the failure being explained."
      }
    ],
    "assertion_conditions": [
      "The observation indicates that an invoked operation did not succeed.",
      "The reasoning identifies a concrete cause for the failure and states a corrective approach or change based on that cause."
    ],
    "exclusion_conditions": [
      "The reasoning merely notes that something failed without offering a causal explanation.",
      "The reasoning explains an unrelated issue or offers no corrective direction."
    ]
  },
  {
    "name": "GUIDES_ACTION",
    "definition": "The action's tool choice, target, or argument values instantiate an intent, diagnosis, or corrected approach explicitly stated in the reasoning.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text stating the plan, diagnosis, or corrected approach."
      },
      {
        "name": "action",
        "type": "action",
        "description": "The action whose tool, target, or arguments carry out that stated approach."
      }
    ],
    "assertion_conditions": [
      "The reasoning specifies the operation or correction to perform, and the action performs that same operation with matching target or arguments.",
      "A traceable correspondence exists between the described step and the executed parameters, command, path, or content."
    ],
    "exclusion_conditions": [
      "The action is unrelated to the described step or diverges from it in target or approach.",
      "The reasoning only reports prior results and the action is merely temporally adjacent."
    ]
  },
  {
    "name": "USES_OBSERVATION_AS_INPUT",
    "definition": "The action uses an identifiable value or payload supplied by a prior observation as an operational input.",
    "parameters": [
      {
        "name": "action",
        "type": "action",
        "description": "The action receiving the input."
      },
      {
        "name": "observation",
        "type": "observation",
        "description": "The prior observation supplying the input value or payload."
      }
    ],
    "assertion_conditions": [
      "An argument, file content, path, or identifier of the action can be traced to content present in the observation.",
      "The observation precedes the action within the trajectory."
    ],
    "exclusion_conditions": [
      "The observation only guides action selection without supplying an operational input value.",
      "The nodes are merely temporally adjacent or topically related without a traceable value transfer."
    ]
  },
  {
    "name": "ATTEMPTS_REPAIR",
    "definition": "The action modifies the command, parameters, or content that previously produced an observed failure in order to address that failure.",
    "parameters": [
      {
        "name": "repair",
        "type": "action",
        "description": "The action attempting to repair the failure."
      },
      {
        "name": "failure",
        "type": "observation",
        "description": "The earlier observation reporting the failure."
      }
    ],
    "assertion_conditions": [
      "The failure observation precedes the repair action and indicates that the operation did not succeed.",
      "The action preserves the original goal while changing the element identified as faulty, such as an option's argument form, a path, or source content."
    ],
    "exclusion_conditions": [
      "The action repeats the failing invocation without any change.",
      "The action pursues a different goal unrelated to the reported failure.",
      "No confirming evidence is required for this predicate; confirmation is a separate mechanism."
    ]
  },
  {
    "name": "CONFIRMS_REPAIR",
    "definition": "A repair action addresses an observed failure, and a subsequent execution result confirms that the original failure has been resolved.",
    "parameters": [
      {
        "name": "repair",
        "type": "action",
        "description": "The action attempting to repair the failure."
      },
      {
        "name": "failure",
        "type": "observation",
        "description": "The earlier observation reporting the failure."
      },
      {
        "name": "check_result",
        "type": "observation",
        "description": "The later observation establishing that the original failure no longer occurs."
      }
    ],
    "assertion_conditions": [
      "The failure precedes the repair, and the repair changes the failing element.",
      "The later result shows the target operation or content being produced, loaded, or otherwise completed successfully, with no recurrence of the original error."
    ],
    "exclusion_conditions": [
      "The repair is attempted without any later result.",
      "The later output repeats the original error or otherwise fails to establish resolution."
    ]
  },
  {
    "name": "REPORTS_FAILURE",
    "definition": "The observation indicates that the invoked operation did not succeed.",
    "parameters": [
      {
        "name": "observation",
        "type": "observation",
        "description": "The tool result being evaluated for failure."
      }
    ],
    "assertion_conditions": [
      "The observation carries an error indication, a non-success exit status, or an explicit error message such as a missing file or unloadable module."
    ],
    "exclusion_conditions": [
      "The observation reports successful completion or plain data output without any error indication."
    ]
  },
  {
    "name": "REPORTS_SUCCESS",
    "definition": "The observation indicates that the invoked operation completed successfully.",
    "parameters": [
      {
        "name": "observation",
        "type": "observation",
        "description": "The tool result being evaluated for success."
      }
    ],
    "assertion_conditions": [
      "The observation contains an explicit success message, a clean completion with no error indication, or a listing of the expected produced artifacts."
    ],
    "exclusion_conditions": [
      "The observation reports an error or non-success exit status.",
      "The output is only a partial or ambiguous progress message."
    ]
  },
  {
    "name": "IS_COMPLETION_CONCLUSION",
    "definition": "The reasoning declares the overall objective achieved and cites the verification evidence that supports the claim.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text asserting task completion."
      }
    ],
    "assertion_conditions": [
      "The reasoning states that the requested objective has been fulfilled.",
      "It references concrete evidence obtained earlier, such as produced artifacts or verified output."
    ],
    "exclusion_conditions": [
      "The reasoning states plans or intermediate steps while work remains.",
      "The reasoning reports observations without concluding that the objective is achieved."
    ]
  }
]

Return existing/new/uncertain with complete accounting and unchanged candidate definitions.
